from tools.scan_demand import parse_sumo_stats

# Sample mirrors real SUMO 1.27.1 statistic-output structure (calibrated
# against a real stats.xml generated by a Task 3 smoke run): vehicle counts
# live in a separate <vehicles> element, not on <performance>.
STATS = """<?xml version="1.0"?>
<statistics>
    <performance clockBegin="0.0" clockEnd="1.0" clockDuration="1.0"
        begin="0.00" end="963.00" duration="963.00"/>
    <vehicles loaded="100" inserted="100" running="0" waiting="0"/>
    <teleports total="0" jam="0" yield="0" wrongLane="0"/>
    <safety collisions="2" emergencyStops="1" emergencyBraking="3"/>
    <vehicleTripStatistics count="100" routeLength="1500.0" speed="25.0"
        duration="60.0" waitingTime="5.0" timeLoss="12.5" departDelay="1.0"/>
</statistics>
"""


def test_parse_sumo_stats():
    m = parse_sumo_stats(STATS)
    assert m["collisions"] == 2
    assert m["teleports"] == 0
    assert m["arrived"] == 100
    assert abs(m["mean_time_loss"] - 12.5) < 1e-9
    assert abs(m["mean_tt"] - 60.0) < 1e-9


def test_main_skips_cell_missing_trip_statistics(monkeypatch, capsys, tmp_path):
    # Without --duration-log.statistics the stats XML omits
    # <vehicleTripStatistics>, so mean_tt/mean_time_loss come back None.
    # main() must skip that cell with a warning instead of crashing on
    # f"{None:.1f}" (TypeError).
    import json
    import sys

    import tools.scan_demand as sd

    def fake_scan_cell(mainline_vph, ramp_vph, seed, duration_s=900):
        return {
            "arrived": 10,
            "mean_tt": None,
            "mean_time_loss": None,
            "teleports": 0,
            "collisions": 0,
            "mainline_vph": mainline_vph,
            "ramp_vph": ramp_vph,
            "seed": seed,
        }

    monkeypatch.setattr(sd, "scan_cell", fake_scan_cell)
    monkeypatch.setattr(
        sys,
        "argv",
        [
            "scan_demand.py",
            "--mainline-rates",
            "1400",
            "--seeds",
            "42",
            "--out-dir",
            str(tmp_path),
        ],
    )
    sd.main()  # must not raise TypeError

    rows = json.loads((tmp_path / "scan_results.json").read_text(encoding="utf-8"))
    assert rows == []
    err = capsys.readouterr().err
    assert "WARNING" in err
    assert "1400" in err and "42" in err
